('international-understanding','test','跨文化沟通与媒介辨识测试','检验文化解释、信息来源、偏见识别和合作沟通能力。','识别刻板印象|核验国际信息|进行尊重沟通','阅读情境|判断表达|修正方案','国际理解综合测试',25,30),
('international-understanding','material','区域比较研究工具包','提供区域指标、文化访谈、媒体来源评估和可持续发展目标对照模板。','选择可比指标|规范跨文化访谈|注明资料边界','阅读示例|选择工具|完成比较框架','区域比较研究框架',18,40)
) AS v(slug,content_type,title,description,objectives,steps,deliverable,duration,sort_order)
ON c.slug=v.slug
WHERE NOT EXISTS (SELECT 1 FROM course_contents cc WHERE cc.course_id=c.id AND cc.title=v.title);
